      "Step 3: $n(\\text{H}_2\\text{O}) = \\frac{1.87}{18}$, $n(\\text{CuSO}_4) = \\frac{3.32}{159.5}$.",
      "Step 4: $x = \\frac{n(\\text{H}_2\\text{O})}{n(\\text{CuSO}_4)} = 5$. Formula: $\\text{CuSO}_4 \\cdot 5\\text{H}_2\\text{O}$."
